def transform(grid):
    # Remove the monochrome 3-object (the unmarked solid object), retaining all others.
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (3, 9) or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx] in (3,9) and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            if all(grid[y][x]==3 for y,x in comp):
                for y,x in comp: out[y][x]=0
    return out
